    ['**/*/*.js', {}, ['src/a.js', 'src/deep/c.js', 'src/deep/deeper/d.js', 'test/a.test.js']],
    ['*/*/*', {}, ['src/deep/c.js', 'x/y/z']],
  ];
  for (const [pattern, options, expected] of cases) {
    assert.deepStrictEqual(filter(UNIVERSE, pattern, options), expected, `pattern ${pattern}`);
  }
});

